pub fn HSD_RObjAddAnimAll<'a>(ctx: &'a Ctx, robj: HSD_RObj<'a>, anim: HSD_RObjAnimJoint<'a>) {
    let __frame = ctx.stack_frame(0x18);
    let mut robj = robj;
    let mut anim = anim;
    let mut i: HSD_RObj<'a> = null(ctx);
    let mut j: HSD_RObjAnimJoint<'a> = null(ctx);
    if (Handle::is_null(robj)) || (Handle::is_null(anim)) {
        return;
    }
    {
        i = robj;
        j = anim;
        'l1: while (!Handle::is_null(i)) && (!Handle::is_null(j)) {
            'c2: {
                inl_HSD_RObjAddAnim_unfused(ctx, i, j);
            }
            i = (i).next();
            j = (j).next();
        }
    }
}

