pub fn resolveCnsDirUp<'a>(
    ctx: &'a Ctx,
    robj: HSD_RObj<'a>,
    obj: Addr<'a>,
    update_func: FnPtr<'a>,
) {
    let __frame = ctx.stack_frame(0x60);
    let this_scale: Vec<'a> = frame_at(ctx, &__frame, 0x3c);
    let up: Vec<'a> = frame_at(ctx, &__frame, 0x30);
    let this_pos: Vec<'a> = frame_at(ctx, &__frame, 0x24);
    let dir: Vec<'a> = frame_at(ctx, &__frame, 0x18);
    let __inl: ArrV<'a, u8, 8> = frame_at(ctx, &__frame, 0x0);
    let mut robj = robj;
    let mut obj = obj;
    let mut update_func = update_func;
    this_scale.set_x(1.0);
    this_scale.set_y(1.0);
    this_scale.set_z(1.0);
    up.set_x(0.0);
    up.set_y(1.0);
    up.set_z(0.0);
    let mut k: f64 = 0.0;
    if fns::HSD_RObjGetGlobalPosition(ctx, robj, 2_i32, this_pos) != 0_i32 {
        dir.set_x(
            (Handle::cast::<HSD_JObj<'a>>(obj))
                .mtx()
                .get(0_i32)
                .at(3_i32)
                .get(),
        );
        dir.set_y(
            (Handle::cast::<HSD_JObj<'a>>(obj))
                .mtx()
                .get(1_i32)
                .at(3_i32)
                .get(),
        );
        dir.set_z(
            (Handle::cast::<HSD_JObj<'a>>(obj))
                .mtx()
                .get(2_i32)
                .at(3_i32)
                .get(),
        );
        fns::PSVECSubtract(ctx, this_pos, dir, this_pos);
        if fns::HSD_RObjGetGlobalPosition(ctx, robj, 3_i32, up) != 0_i32 {
            fns::PSVECSubtract(ctx, up, dir, up);
        } else {
            k = fp::fsubs(1.0, fns::PSVECDotProduct(ctx, this_pos, up));
            if inl_fabsf_bitwise_unfused(ctx, k, Handle::addr(__inl)) < 1.000000013351432e-10_f64 {
                up.set_x(0.0);
                up.set_y(0.0);
                up.set_z(fp::frsp(1.0));
            }
        }
        if !Handle::is_null((Handle::cast::<HSD_JObj<'a>>(obj)).scl()) {
            Handle::copy_from(this_scale, ((Handle::cast::<HSD_JObj<'a>>(obj)).scl()));
        }
        statics::sysdolphin__baselib__robj::set_dirup_matrix(
            ctx,
            this_pos,
            up,
            this_scale,
            obj,
            update_func,
        );
    }
}

pub fn resolveCnsOrientation<'a>(ctx: &'a Ctx, a0: HSD_RObj<'a>, a1: Addr<'a>, a2: FnPtr<'a>) {
    // Transliterated from its machine code: leaves f2, f3, f4 as itSamusmissile_UnkMotion0_Phys, ported from machine code, reads it.
    (a0, a1, a2).put_regs(ctx);
    asm_resolveCnsOrientation(ctx);
}

