pub fn HSD_RvalueRemoveAll<'a>(ctx: &'a Ctx, rvalue: HSD_Rvalue<'a>) {
    let __frame = ctx.stack_frame(0x20);
    let mut rvalue = rvalue;
    let mut next: HSD_Rvalue<'a> = null(ctx);
    {
        'l1: while !Handle::is_null(rvalue) {
            'c2: {
                next = (rvalue).next();
                inl_HSD_RvalueRemove_unfused(ctx, rvalue);
            }
            rvalue = next;
        }
    }
}

pub fn expLoadDesc<'a>(ctx: &'a Ctx, exp: HSD_Exp<'a>, desc: HSD_ExpDesc<'a>) {
    let __frame = ctx.stack_frame(0x38);
    let __inl: ArrV<'a, u8, 8> = frame_at(ctx, &__frame, 0x10);
    let mut exp = exp;
    let mut desc = desc;
    let _ = fns::memset(ctx, Handle::cast::<Addr<'a>>(exp), 0_i32, 16_u32);
    if !Handle::is_null(desc) {
        if !Handle::is_null((desc).func()) {
            (exp).expr().set_func((desc).func());
        } else {
            (exp).expr().set_func(fnptr(ctx, 0x8037c950));
        }
        (exp).set_rvalue(inl_loadRvalue_unfused(
            ctx,
            (desc).rvalue(),
            Handle::addr(__inl),
        ));
        (exp).set_nb_args((1_i32.wrapping_neg() as u32));
    }
}

pub fn bcexpLoadDesc<'a>(ctx: &'a Ctx, exp: HSD_Exp<'a>, desc: HSD_ByteCodeExpDesc<'a>) {
    let __frame = ctx.stack_frame(0x38);
    let __inl: ArrV<'a, u8, 8> = frame_at(ctx, &__frame, 0x10);
    let mut exp = exp;
    let mut desc = desc;
    let _ = fns::memset(ctx, Handle::cast::<Addr<'a>>(exp), 0_i32, 16_u32);
    if !Handle::is_null(desc) {
        if !Handle::is_null((desc).bytecode()) {
            (exp).expr().set_bytecode((desc).bytecode());
        } else {
            (exp).expr().set_bytecode(null::<Val<'a, u8>>(ctx));
        }
        (exp).set_rvalue(inl_loadRvalue_unfused(
            ctx,
            (desc).rvalue(),
            Handle::addr(__inl),
        ));
        (exp).set_nb_args((1_i32.wrapping_neg() as u32));
        (exp).set_is_bytecode((1_i32 as u8));
    }
}

